    @Override
    public void addCorsMappings(CorsRegistry registry) {
        registry.addMapping("/**")
                .allowedMethods("HEAD", "GET", "PUT", "POST", "DELETE", "PATCH");
    }
}
</code></pre>

<p>If you are using Spring Boot:</p>

<pre><code>@Configuration
